        try:
            with open(path, "r", newline="", encoding="utf-8-sig") as f:
                rows = list(csv.reader(f, delimiter=delimiter, quotechar=quotechar))
        except FileNotFoundError:
            raise
        except Exception as exc:
            raise Exception(str(exc)) from exc

        if len(rows) == 0:
            raise ValueError(f"File '{path}' is empty.")

        return rows

    def normalize_row(row):
        # Serialize each CSV row back to a canonical line representation.
        from io import StringIO

        buffer = StringIO()
        writer = csv.writer(buffer, delimiter=delimiter, quotechar=quotechar, lineterminator="")
        writer.writerow(row)
        return buffer.getvalue()

    rows1 = [normalize_row(row) for row in read_rows(file_path1)]
    rows2 = [normalize_row(row) for row in read_rows(file_path2)]

    report = []
    line_num1 = 1
    line_num2 = 1

    for diff_item in ndiff(rows1, rows2):
        status = diff_item[:2]
        content = diff_item[2:]

        if status == "  ":
            report.append({
                "Line Number": line_num1,
                "Status": " ",
                "Content": content
            })
            line_num1 += 1
            line_num2 += 1
        elif status == "- ":
            report.append({
                "Line Number": line_num1,
                "Status": "-",
                "Content": content
            })
            line_num1 += 1
        elif status == "+ ":
            report.append({
                "Line Number": line_num2,
                "Status": "+",
                "Content": content
            })
            line_num2 += 1

    return pd.DataFrame(report, columns=["Line Number", "Status", "Content"])
